// === Tab: mySketch ===
let constellation = [];
let n;
let d;
let c;
const palettes = [
	['#00FFaF','#000020'],
	['#aF00FF','#000020'],
];

function setup() {
  createCanvas(420, 420);
  pixelDensity(1);
  n = width/2;
	c = createVector(width/2, height/2);
  for (let i = 0; i <= n; i++) {
    constellation.push(new star());
  }
	strokeWeight(random(0.05,0.15));
}

function draw() {
	noFill();
	stroke(palettes[0][0]);
  background(palettes[0][1]);

  for (let i = 0; i < constellation.length; i++) {
		const s1 = constellation[i];
    s1.update();

    for (let j = 0; j < constellation.length; j++) {
      if (i > j) {
				const s2 = constellation[j];

        if (s1.loc.dist(s2.loc) <= width/8) {
          line(s1.loc.x, s1.loc.y, s2.loc.x, s2.loc.y);
        }
      }
    }
  }

	fill('#000020');
	noStroke();
	ellipse(c.x,c.y,width/2.05,width/2.05);
}

function star() {

  this.a = random(5 * TAU);
  this.r = random(width/8, width/2);
  this.loc = createVector(c.x + sin(this.a) * this.r, c.y + cos(this.a) * this.r);
	this.speed = p5.Vector.random2D();

  this.update = function() {
			var d = c.dist(this.loc);

			if(((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed))) {
      	if (d < width/2) {
					if(c.dist(createVector((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))),(window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))))) > width/4) {
						this.loc = p5.Vector.lerp(this.loc, c, random(-0.3,0.2));
					} else {
						this.loc = p5.Vector.lerp(this.loc, c, -0.2);
					}
					this.speed.normalize().mult(random(0.5,1.5));
				}
			} else {
				if (d > width/4) {
					this.loc = p5.Vector.lerp(this.loc, c, 0.02);
				}
			}

			// bounds
      if (dist(this.loc.x, this.loc.y, width/2, height/2) > 3*width/2) {
        if (this.loc.x < width/2) {
          this.loc.x = width - this.loc.x-4;
        } else if (this.loc.x > width/2) {
          this.loc.x = width - this.loc.x+4;
        }
        if (this.loc.y < 3*height/2) {
          this.loc.y = height - this.loc.y-4;
        } else if (this.loc.x > height/2) {
          this.loc.y = height - this.loc.y+4;
        }
      }

			this.loc.add(this.speed);
    }
}

